import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';
import { MOTUS_PUBLIC_CATEGORY_SLUGS } from '../src/content/publisher-schema.js';
import { assertPeriodicContentQuality, buildReportArchiveView, createPeriodicProductionRun, deriveInstitutionSignals, detectPeriodChanges, renderWeeklyIntelligence, reportCtas } from '../src/intelligence/periodic-production.js';
test('Sprint 4F creates Weekly and Monthly VMs from verified Daily records', () => { const run = createPeriodicProductionRun(); assert.equal(run.weekly.metadata.category, 'WEEKLY_INTELLIGENCE'); assert.equal(run.monthly.metadata.category, 'MONTHLY_INTELLIGENCE'); assert.deepEqual(run.weekly.metadata.observedDates, ['2026-09-29', '2026-09-30']); assert.equal(run.weekly.metadata.review.state, 'PENDING'); assert.equal(run.monthly.metadata.review.state, 'PENDING'); assert.equal(run.weekly.metadata.readiness, 'HOLD'); assert.equal(run.monthly.metadata.readiness, 'HOLD'); assert.ok(run.weekly.aiIntelligence.length >= 3); assert.ok(run.monthly.eventToMarketReview?.length); });
test('Sprint 4F aggregates an actual week range and never invents a trend without history', () => { assert.deepEqual(detectPeriodChanges([{ key: 'ai', label: 'AI', count: 2, evidenceIds: ['e2'], sourceIds: ['s2'] }]), []); const prior = [{ key: 'ai', label: 'AI', count: 1, evidenceIds: ['e1'], sourceIds: ['s1'] }, { key: 'old', label: 'Old', count: 1, evidenceIds: ['e0'], sourceIds: ['s0'] }]; const current = [{ key: 'ai', label: 'AI', count: 2, evidenceIds: ['e2'], sourceIds: ['s2'] }, { key: 'new', label: 'New', count: 1, evidenceIds: ['e3'], sourceIds: ['s3'] }]; const changes = detectPeriodChanges(current, prior); assert.equal(changes.find(item => item.key === 'ai')?.state, 'INCREASED'); assert.equal(changes.find(item => item.key === 'new')?.state, 'NEW'); assert.equal(changes.find(item => item.key === 'old')?.state, 'RESOLVED'); assert.deepEqual(changes.find(item => item.key === 'ai')?.evidenceIds, ['e1', 'e2']); });
test('Sprint 4F consensus requires two institutions and evidence', () => { const one = { institution: 'A', reportId: 'r1', publishedAt: '2026-09-29', key: 'agent', direction: 'POSITIVE', summary: '실행 확대', evidenceIds: ['e1'], sourceIds: ['s1'] }; assert.equal(deriveInstitutionSignals([one]).consensus.length, 0); assert.equal(deriveInstitutionSignals([one, { ...one, institution: 'B', reportId: 'r2', evidenceIds: [] }]).consensus.length, 0); const result = deriveInstitutionSignals([one, { ...one, institution: 'B', reportId: 'r2', evidenceIds: ['e2'], sourceIds: ['s2'] }]); assert.equal(result.consensus.length, 1); assert.deepEqual(result.consensus[0]?.institutions, ['A', 'B']); });
test('Sprint 4F divergence requires independent institutions and opposing evidenced views', () => { const base = { institution: 'A', reportId: 'r1', publishedAt: '2026-09-29', key: 'rates', direction: 'POSITIVE', summary: '성장 우호', evidenceIds: ['e1'], sourceIds: ['s1'] }; assert.equal(deriveInstitutionSignals([base, { ...base, institution: 'B', reportId: 'r2', direction: 'NEGATIVE', evidenceIds: [] }]).divergence.length, 0); const result = deriveInstitutionSignals([base, { ...base, institution: 'B', reportId: 'r2', direction: 'NEGATIVE', summary: '할인율 부담', evidenceIds: ['e2'], sourceIds: ['s2'] }]); assert.equal(result.divergence.length, 1); assert.match(result.divergence[0].direction, /POSITIVE vs NEGATIVE/); });
test('Sprint 4F Event-to-Market review is null-safe and preserves internal provenance outside public HTML', () => { const run = createPeriodicProductionRun(); const item = run.monthly.eventToMarketReview[0]; assert.equal(item.subsequentMarketReaction, null); assert.ok(item.evidenceRefs.length); assert.doesNotMatch(run.monthlyRender.html, /event:|theme:|company:|EVIDENCE-|verificationStatus|confidence/); assert.match(run.monthlyRender.html, /Event → Market Review/); });
test('Sprint 4F omits unsupported Consensus, Divergence and change sections', () => { const run = createPeriodicProductionRun(); assert.equal(run.weekly.institutionalConsensus, undefined); assert.equal(run.weekly.institutionalDivergence, undefined); assert.equal(run.weekly.themeChanges, undefined); assert.doesNotMatch(run.weeklyRender.html, /기관 공통 의견|기관별 차이|이번 주 변화/); assert.doesNotMatch(run.weeklyRender.html, /No data|자료 부족|placeholder/i); });
test('Sprint 4F dedupes public sources by canonical URL plus publisher', () => { const run = createPeriodicProductionRun(); const copy = structuredClone(run.weekly); copy.sources.push({ ...copy.sources[0], url: `${copy.sources[0].url}?utm_source=again` }); const html = renderWeeklyIntelligence(copy).html; const label = copy.sources[0].label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); assert.equal((html.match(new RegExp(`>${label}<`, 'g')) ?? []).length, 1); assert.doesNotMatch(html, /utm_source/); });
test('Sprint 4F Reports groups and filters entries and gates both CTAs', () => { const base = { title: 'Daily', issueDate: '2026-09-30', periodStart: '2026-09-30', periodEnd: '2026-09-30', category: 'US_MARKET', reportType: 'US_MARKET_DAILY', downloadUrl: null, articleUrl: null, generatedAt: '2026-10-01T00:00:00Z', publishedAt: null, state: 'PREVIEW_READY' }; const entries = [base, { ...base, title: 'Weekly', category: 'WEEKLY_INTELLIGENCE', reportType: 'WEEKLY_INTELLIGENCE', state: 'AVAILABLE', downloadUrl: 'https://motusnova.blogspot.com/reports/w40.pdf', articleUrl: 'https://motusnova.blogspot.com/2026/10/weekly.html' }, { ...base, title: 'Monthly', issueDate: '2026-08-31', category: 'MONTHLY_INTELLIGENCE', reportType: 'MONTHLY_INTELLIGENCE' }]; const view = buildReportArchiveView(entries, { year: 2026, month: 9 }); assert.deepEqual(view.groups.map(group => group.group), ['Daily', 'Weekly']); assert.deepEqual(reportCtas(entries[0]), { download: null, article: null }); assert.ok(reportCtas(entries[1]).download); assert.ok(reportCtas(entries[1]).article); });
test('Sprint 4F PDF CTA rejects non-HTTPS, non-PDF and unavailable values', () => { const base = { title: 'x', issueDate: '2026-09-30', category: 'REPORTS', reportType: 'WEEKLY_INTELLIGENCE', downloadUrl: 'http://example.org/file.pdf', articleUrl: 'https://example.org', generatedAt: '2026-10-01T00:00:00Z', state: 'AVAILABLE' }; assert.deepEqual(reportCtas(base), { download: null, article: null }); assert.equal(reportCtas({ ...base, downloadUrl: 'https://example.org/page' }).download, null); assert.deepEqual(reportCtas({ ...base, state: 'PREVIEW_READY', downloadUrl: 'https://example.org/file.pdf', articleUrl: 'https://example.org/post' }), { download: null, article: null }); });
test('Sprint 4F applies the same market color master to Blogger-safe and PDF outputs', () => { const run = createPeriodicProductionRun(); for (const html of [run.weeklyRender.html, run.monthlyRender.html]) {
    assert.match(html, /#c62828/);
    assert.match(html, /#1565c0/);
    assert.match(html, /max-width:100%/);
    assert.doesNotMatch(html, /<style\b|<script\b|<iframe\b/);
} assert.equal(run.weeklyPdf.colorMaster.positive, '#c62828'); assert.equal(run.monthlyPdf.colorMaster.negative, '#1565c0'); });
test('Sprint 4F PDF foundations derive from the verified VMs rather than Blogger HTML', () => { const run = createPeriodicProductionRun(); assert.equal(run.weeklyPdf.format, 'WEEKLY_COMPACT'); assert.deepEqual(run.weeklyPdf.targetPages, { min: 3, max: 5 }); assert.equal(run.monthlyPdf.format, 'MONTHLY_LONG_FORM'); assert.ok(run.weeklyPdf.sections.length); assert.ok(run.monthlyPdf.sections.length); assert.equal(JSON.stringify(run.weeklyPdf).includes('<main'), false); });
test('Sprint 4F content quality gate requires context, evidence and next watch', () => { assert.throws(() => assertPeriodicContentQuality({ summary: '짧음', sections: [], sources: [], nextWatch: [] }), /context and meaning/); assert.throws(() => assertPeriodicContentQuality({ summary: '시장 변화의 배경과 의미를 충분한 길이로 설명하지만 다음 확인 조건과 근거가 필요한 상태를 구체적으로 설명한다. 금리와 기업 실적이 서로 어떤 영향을 주는지도 확인해야 하며 독자가 판단할 수 있는 맥락을 함께 제공한다.', sections: [], sources: [], nextWatch: ['확인'] }), /evidence/); assert.doesNotThrow(() => assertPeriodicContentQuality({ summary: '금리 변화 때문에 시장의 할인율 부담이 커졌고 확인 가능한 자료 범위 안에서 기업과 업종의 의미를 충분히 설명한다. 다음 거래일에는 실제 금리와 시장 폭을 함께 확인할 필요가 있으며 단정적인 전망은 피한다.', sections: [], sources: [{ label: 'Source', url: 'https://example.org/source', publisher: 'Source' }], nextWatch: ['금리 확인'] })); });
test('Sprint 4F exposes the canonical public hierarchy and keeps Commerce disabled', () => { assert.deepEqual(MOTUS_PUBLIC_CATEGORY_SLUGS, { AI_INTELLIGENCE: 'ai-intelligence', US_MARKET: 'us-market', KOREA_MARKET: 'korea-market', WEEKLY_INTELLIGENCE: 'weekly-intelligence', MONTHLY_INTELLIGENCE: 'monthly-intelligence', REPORTS: 'reports' }); const run = createPeriodicProductionRun(); assert.deepEqual(run.remoteCalls, { insert: 0, patch: 0, publish: 0, themeUpdate: 0, menuUpdate: 0 }); assert.deepEqual(run.commerce, { enabled: false }); });
test('Sprint 4F leaves the first production post unchanged', () => { const record = JSON.parse(readFileSync('data/blogger/2026-09-29/newsletter-motus-2026-09-29-publication.json', 'utf8')); assert.deepEqual(record, { ...record, status: 'PUBLISHED', draftPostId: '9009523239057574527', publicPostUrl: 'https://motusnova.blogspot.com/2026/09/5-ai.html' }); });
